function executarPDF() {
const { jsPDF } = window.jspdf;
const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
const data = getDadosImpressao();

const navy = [26, 62, 116];
const slateLight = [241, 245, 249];
const W = 210,
marginL = 18,
marginR = 18,
usable = W - marginL - marginR;

// Cabeçalho
doc.setFillColor(...navy);
doc.rect(0, 0, W, 32, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(14);
doc.text("Шкала SOFA", marginL, 13);
doc.setFontSize(9);
doc.setFont("helvetica", "normal");
doc.text("Послідовна оцінка органної недостатності в реанімації", marginL, 20);
doc.text("Дата: " + data.data, W - marginR, 20, { align: "right" });

let y = 42;

// Identificação
if (data.nome || data.idade || data.setor) {
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text("ІДЕНТИФІКАЦІЯ ПАЦІЄНТА", marginL + 4, y + 5.5);
y += 12;

if (data.nome) {
doc.text("Nome:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.nome, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.idade) {
doc.text("Idade:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.idade, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.setor) {
doc.text("Setor/Leito:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.setor, marginL + 25, y);
y += 6;
}
y += 4;
}

// Pontuação Big
doc.setFillColor(...navy);
doc.roundedRect(marginL, y, usable, 22, 3, 3, "F");
doc.setTextColor(147, 197, 253);
doc.setFont("helvetica", "bold");
doc.setFontSize(8);
doc.text(`ЧАС ОЦІНЮВАННЯ: ${data.tempo}`, W / 2, y + 6, { align: "center" });
doc.setTextColor(255, 255, 255);
doc.setFontSize(26);
doc.text(String(data.soma) + " / 24", W / 2, y + 17, { align: "center" });
y += 28;

// Status Pill
let pillColor = [22, 163, 74]; // Verde
if (data.soma >= 5 && data.soma <= 9) pillColor = [234, 179, 8]; // Amarelo
if (data.soma >= 10) pillColor = [225, 29, 72]; // Vermelho

doc.setFillColor(...pillColor);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text(data.classe.toUpperCase(), W / 2, y + 5.5, { align: "center" });
y += 16;

// Tabela AutoTable
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.text("ПАМ'ЯТЬ КЛІНІЧНОЇ ОЦІНКИ", marginL + 4, y + 5.5);
y += 11;

const bodyData = data.dominios.map((d) => {
return [d.nome.replace(/^\d+\.\s*/, ""), d.obtido, d.text];
});

doc.autoTable({
startY: y,
margin: { left: marginL, right: marginR },
head: [["Система / Орган", "Pontos", "Стан / Обрана опція"]],
body: bodyData,
foot: [["ЗАГАЛЬНИЙ SOFA", data.soma, data.classe]],
styles: { fontSize: 8.5, cellPadding: 3, lineColor: [226, 232, 240], lineWidth: 0.3 },
headStyles: { fillColor: navy, textColor: 255, fontStyle: "bold" },
footStyles: { fillColor: [239, 246, 255], textColor: navy, fontStyle: "bold" },
columnStyles: { 0: { cellWidth: 50 }, 1: { halign: "center", cellWidth: 15 }, 2: { halign: "left" } },
alternateRowStyles: { fillColor: [248, 250, 252] },
});

// Rodapé
y = 280;
doc.setDrawColor(...slateLight);
doc.setLineWidth(0.3);
doc.line(marginL, y, W - marginR, y);
doc.setTextColor(148, 163, 184);
doc.setFontSize(7.5);
doc.setFont("helvetica", "normal");
doc.text("VINCENT, J. L. et al. Intensive Care Medicine (1996).", marginL, y + 5);
doc.text("www.calculadorasdeenfermagem.com.br", W - marginR, y + 5, { align: "right" });

const nomeArquivo = data.nome ? `laudo-sofa-${data.nome.replace(/\s+/g, "-").toLowerCase()}.pdf` : "laudo-sofa.pdf";
doc.save(nomeArquivo);
}

